def __getattr__(attr):
    # Warn for expired attributes
    import warnings

    if attr == "linalg":
        import numpy.linalg as linalg
        return linalg
    elif attr == "fft":
        import numpy.fft as fft
        return fft
    elif attr == "dtypes":
        import numpy.dtypes as dtypes
        return dtypes
    elif attr == "random":
        import numpy.random as random
        return random
    elif attr == "polynomial":
        import numpy.polynomial as polynomial
        return polynomial
    elif attr == "ma":
        import numpy.ma as ma
        return ma
    elif attr == "ctypeslib":
        import numpy.ctypeslib as ctypeslib
        return ctypeslib
    elif attr == "exceptions":
        import numpy.exceptions as exceptions
        return exceptions
    elif attr == "testing":
        import numpy.testing as testing
        return testing

def main():
    res = run(['gcc', '-v'], check=True, text=True, capture_output=True)
    target = re.search(r'^Target: (.*)$', res.stderr, flags=re.M).groups()[0]
    if target.startswith('i686'):
        print('32')
    elif target.startswith('x86_64'):
        print('64')
    else:
        raise RuntimeError('Could not detect Mingw-w64 bitness')

def coerce_text(v):
    if not isinstance(v, basestring_):
        if hasattr(v, "__str__"):
            return str(v)
        else:
            return bytes(v)
    return v

def numeric_type_aliases(aliases):
    def type_aliases_gen():
        for alias, doc in aliases:
            try:
                alias_type = getattr(_numerictypes, alias)
            except AttributeError:
                # The set of aliases that actually exist varies between platforms
                pass
            else:
                yield (alias_type, alias, doc)
    return list(type_aliases_gen())

def _kind_name(dtype):
    try:
        return _kind_to_stem[dtype.kind]
    except KeyError as e:
        raise RuntimeError(
            f"internal dtype error, unknown kind {dtype.kind!r}"
        ) from None

def _unpack_tuple(tup):
    if len(tup) == 1:
        return tup[0]
    else:
        return tup

